    # Testing resolution with multiple requirements
    versions = [f"1.{j}.0" for j in range(20)]
    resolver = VersionResolver(versions)
    # req: ^1.{i}.0 and <=1.{i+5}.0
    reqs = [f"^1.{i}.0", f"<=1.{i+5}.0"]
