# TEST FINGERPRINT COMPUTER
# ============================================================================
class TestContractFingerprintComputer:
    """Test ContractFingerprintComputer."""

    @pytest.fixture
    def f_testcontractversioning01_computer(self):
        return ContractFingerprintComputer()

    @pytest.fixture
    def f_testcontractversioning01_sample_clauses(self):
        return [
            {
                "clause_id": "clause_1",
                "clause_type": "layout",
                "subject_reference": {"entity_id": "struct_Point"},
                "constraint_parameters": [
                    {"name": "size_bytes", "value": 8},
                    {"name": "alignment", "value": 4},
                ],
            },
            {
                "clause_id": "clause_2",
                "clause_type": "nullability",
                "subject_reference": {"entity_id": "function_get_data"},
                "constraint_parameters": [{"name": "nullable", "value": False}],
            },
        ]

    def test_compute_fingerprint_deterministic(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test fingerprint computation is deterministic."""
        fp1 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        fp2 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        assert fp1 == fp2
        assert len(fp1) == 64  # SHA-256 hex digest

    def test_fingerprint_changes_with_ir(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test fingerprint changes when IR changes."""
        fp1 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        fp2 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="b" * 64,  # Different IR
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        assert fp1 != fp2

    def test_fingerprint_changes_with_schema_version(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test fingerprint changes when schema version changes."""
        fp1 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        fp2 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.1.0",  # Different schema
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        assert fp1 != fp2

    def test_fingerprint_changes_with_synthesis_version(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test fingerprint changes when synthesis version changes."""
        fp1 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        fp2 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.1.0",  # Different synthesis
            clauses=f_testcontractversioning01_sample_clauses,
        )

        assert fp1 != fp2

    def test_fingerprint_changes_with_clause_content(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test fingerprint changes when clause content changes."""
        fp1 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        modified_clauses = [
            {
                "clause_id": "clause_1",
                "clause_type": "layout",
                "subject_reference": {"entity_id": "struct_Point"},
                "constraint_parameters": [
                    {"name": "size_bytes", "value": 16},  # Changed size
                    {"name": "alignment", "value": 4},
                ],
            },
            f_testcontractversioning01_sample_clauses[1],
        ]

        fp2 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=modified_clauses,
        )

        assert fp1 != fp2

    def test_fingerprint_invariant_to_clause_order(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test fingerprint doesn't change with clause reordering."""
        fp1 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=f_testcontractversioning01_sample_clauses,
        )

        # Reverse clause order
        reversed_clauses = list(reversed(f_testcontractversioning01_sample_clauses))

        fp2 = f_testcontractversioning01_computer.compute_fingerprint(
            ir_fingerprint="a" * 64,
            schema_version="1.0.0",
            synthesis_version="1.0.0",
            clauses=reversed_clauses,
        )

        # Should be identical due to canonicalization
        assert fp1 == fp2

    def test_invalid_ir_fingerprint(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test invalid IR fingerprint raises error."""
        with pytest.raises(ValueError, match="Invalid fingerprint"):
            f_testcontractversioning01_computer.compute_fingerprint(
                ir_fingerprint="invalid",
                schema_version="1.0.0",
                synthesis_version="1.0.0",
                clauses=f_testcontractversioning01_sample_clauses,
            )

    def test_invalid_version_format(self, f_testcontractversioning01_computer, f_testcontractversioning01_sample_clauses):
        """Test invalid version format raises error."""
        with pytest.raises(ValueError, match="Invalid version"):
            f_testcontractversioning01_computer.compute_fingerprint(
                ir_fingerprint="a" * 64,
                schema_version="1.0",  # Invalid
                synthesis_version="1.0.0",
                clauses=f_testcontractversioning01_sample_clauses,
            )


