# TEST SCHEMA COMPATIBILITY DETECTOR
# ============================================================================
class TestSchemaCompatibilityDetector:
    """Test SchemaCompatibilityDetector."""

    @pytest.fixture
    def f_testcontractversioning02_detector(self):
        return SchemaCompatibilityDetector()

    @pytest.mark.parametrize(
        "v1, v2, expected",
        [
            ("1.0.0", "1.0.0", SchemaCompatibility.IDENTICAL),
            ("1.0.0", "1.1.0", SchemaCompatibility.BACKWARD_COMPATIBLE),
            ("1.1.0", "1.0.0", SchemaCompatibility.FORWARD_COMPATIBLE),
            ("1.0.0", "1.0.1", SchemaCompatibility.PATCH_DIFFERENCE),
            ("1.0.1", "1.0.0", SchemaCompatibility.PATCH_DIFFERENCE),
            ("1.0.0", "2.0.0", SchemaCompatibility.BREAKING_INCOMPATIBLE),
            ("2.0.0", "1.0.0", SchemaCompatibility.BREAKING_INCOMPATIBLE),
            ("1.2.3", "1.2.4", SchemaCompatibility.PATCH_DIFFERENCE),
            ("1.2.4", "1.2.3", SchemaCompatibility.PATCH_DIFFERENCE),
            ("2.1.5", "2.1.4", SchemaCompatibility.PATCH_DIFFERENCE),
            ("0.1.0", "0.2.0", SchemaCompatibility.BACKWARD_COMPATIBLE),
            ("1.0.0", "10.0.0", SchemaCompatibility.BREAKING_INCOMPATIBLE),
            ("1.0.0", "1.100.0", SchemaCompatibility.BACKWARD_COMPATIBLE),
            ("3.0.0", "3.0.0", SchemaCompatibility.IDENTICAL),
            ("3.0.0", "3.1.0", SchemaCompatibility.BACKWARD_COMPATIBLE),
            ("3.1.0", "3.0.0", SchemaCompatibility.FORWARD_COMPATIBLE),
            ("4.5.6", "4.5.7", SchemaCompatibility.PATCH_DIFFERENCE),
            ("4.5.7", "4.5.6", SchemaCompatibility.PATCH_DIFFERENCE),
        ],
    )
    def test_compatibility_matrix(self, f_testcontractversioning02_detector, v1, v2, expected):
        assert f_testcontractversioning02_detector.detect_compatibility(v1, v2) == expected

    def test_detect_unknown_future(self, f_testcontractversioning02_detector):
        """Test detecting unknown future version."""
        compat = f_testcontractversioning02_detector.detect_compatibility("invalid", "1.0.0")
        assert compat == SchemaCompatibility.UNKNOWN_FUTURE

    def test_is_compatible_logic(self, f_testcontractversioning02_detector):
        assert f_testcontractversioning02_detector.is_compatible("1.0.0", "1.1.0") is True
        assert f_testcontractversioning02_detector.is_compatible("1.0.0", "2.0.0") is False

    def test_requires_migration_logic(self, f_testcontractversioning02_detector):
        assert f_testcontractversioning02_detector.requires_migration("1.0.0", "2.0.0") is True
        assert f_testcontractversioning02_detector.requires_migration("1.0.0", "1.1.0") is False

    def test_can_downgrade_logic(self, f_testcontractversioning02_detector):
        # Implementation: can_downgrade(new, old) -> detect(old, new) == BACKWARD
        # detect("1.0.0", "1.1.0") is BACKWARD_COMPATIBLE.
        assert f_testcontractversioning02_detector.can_downgrade("1.1.0", "1.0.0") is True
        assert f_testcontractversioning02_detector.can_downgrade("1.0.0", "1.1.0") is False  # detect(1.1, 1.0) == FORWARD

    def test_detect_deprecated_version(self):
        f_testcontractversioning02_registry = SchemaEvolutionRegistry()
        f_testcontractversioning02_registry.register_version(
            SchemaVersionInfo("1.0.0", "date", SchemaVersionStatus.DEPRECATED)
        )
        f_testcontractversioning02_detector = SchemaCompatibilityDetector(f_testcontractversioning02_registry)
        assert (
            f_testcontractversioning02_detector.detect_compatibility("1.0.0", "1.1.0") == SchemaCompatibility.DEPRECATED_VERSION
        )


