class TestABICompatibilityDetector:
    """Test ABICompatibilityDetector."""

    @pytest.fixture
    def f_testcontractversioning04_detector(self):
        return ABICompatibilityDetector()

    @pytest.fixture
    def f_testcontractversioning04_mock_contract_v1(self):
        """Mock contract version 1.0.0."""

        class MockContract:
            contract_version = "1.0.0"
            contract_fingerprint = "a" * 64
            functions = []
            structs = []

        return MockContract()

    @pytest.fixture
    def f_testcontractversioning04_mock_contract_v1_1(self):
        """Mock contract version 1.1.0 (compatible extension)."""

        class MockContract:
            contract_version = "1.1.0"
            contract_fingerprint = "b" * 64
            functions = []
            structs = []

        return MockContract()

    def test_detect_identical_contracts(self, f_testcontractversioning04_detector, f_testcontractversioning04_mock_contract_v1):
        """Test detecting identical contracts."""
        diff = f_testcontractversioning04_detector.detect_compatibility(f_testcontractversioning04_mock_contract_v1, f_testcontractversioning04_mock_contract_v1)

        assert diff.overall_compatibility == ABICompatibility.ABI_IDENTICAL

    def test_detect_different_contracts(self, f_testcontractversioning04_detector, f_testcontractversioning04_mock_contract_v1, f_testcontractversioning04_mock_contract_v1_1):
        """Test detecting different contracts."""
        diff = f_testcontractversioning04_detector.detect_compatibility(f_testcontractversioning04_mock_contract_v1, f_testcontractversioning04_mock_contract_v1_1)

        # Should not be identical
        assert diff.overall_compatibility != ABICompatibility.ABI_IDENTICAL

    def test_detect_added_function(self, f_testcontractversioning04_detector):
        """Test detecting added function."""

        class V1:
            contract_version = "1.0.0"
            contract_fingerprint = "f1"
            functions = [{"function_id": "f_old"}]
            structs = []

        class V2:
            contract_version = "1.1.0"
            contract_fingerprint = "f2"
            functions = [{"function_id": "f_old"}, {"function_id": "f_new"}]
            structs = []

        diff = f_testcontractversioning04_detector.detect_compatibility(V1(), V2())

        assert len(diff.changes) == 1
        assert diff.changes[0].change_type == ChangeType.FUNCTION_ADDED
        assert diff.overall_compatibility == ABICompatibility.ABI_COMPATIBLE_EXTENSION

    def test_detect_removed_function(self, f_testcontractversioning04_detector):
        """Test detecting removed function."""

        class V1:
            contract_version = "1.0.0"
            contract_fingerprint = "f1"
            functions = [{"function_id": "f_old"}]
            structs = []

        class V2:
            contract_version = "1.1.0"
            contract_fingerprint = "f2"
            functions = []
            structs = []

        diff = f_testcontractversioning04_detector.detect_compatibility(V1(), V2())

        assert len(diff.changes) == 1
        assert diff.changes[0].change_type == ChangeType.FUNCTION_REMOVED
        assert diff.overall_compatibility == ABICompatibility.ABI_BREAKING_REMOVAL


