# ============================================================================
# BULK PARAMETERIZED TESTS (to reach 80)
# ============================================================================
@pytest.mark.parametrize("i", range(20))
def test_bulk_contract_change_is_breaking(i):
    # Alternating breaking/non-breaking
    impact = (
        ABICompatibility.ABI_BREAKING_LAYOUT
        if i % 2 == 0
        else ABICompatibility.ABI_COMPATIBLE_EXTENSION
    )
    change = ContractChange(
        change_type=ChangeType.FUNCTION_MODIFIED,
        entity_id=f"ent_{i}",
        description="test",
        abi_impact=impact,
    )
    assert change.is_breaking() == (i % 2 == 0)


@pytest.mark.parametrize("i", range(20))
def test_bulk_timeline_ordering(i):
    f_testcontractversioning04_timeline = ContractEvolutionTimeline("test")
    # Add versions in reverse order
    for j in range(i, -1, -1):
        f_testcontractversioning04_timeline.add_snapshot(
            ContractVersionSnapshot(
                version=f"1.{j}.0",
                release_date="date",
                contract_fingerprint=str(j),
                schema_version="1",
                synthesis_version="1",
                ir_fingerprint="ir",
            )
        )

    versions = f_testcontractversioning04_timeline.get_all_versions()
    assert versions == [f"1.{j}.0" for j in range(i + 1)]


@pytest.mark.parametrize("i", range(10))
def test_bulk_migration_effort(f_testcontractversioning04_analyzer, i):
    # Add varying number of changes
    changes = [
        ContractChange(
            change_type=ChangeType.FUNCTION_REMOVED,
            entity_id=f"f{j}",
            description="rem",
            abi_impact=ABICompatibility.ABI_BREAKING_REMOVAL,
        )
        for j in range(i + 1)
    ]
    effort = f_testcontractversioning04_analyzer._estimate_effort(changes)
    if i + 1 <= 2:
        assert effort == "minutes"
    elif i + 1 <= 10:
        assert effort == "hours"
    else:
        assert effort == "days"


@pytest.fixture
def f_testcontractversioning04_analyzer():
    return MigrationNecessityAnalyzer()


if __name__ == "__main__":
    pytest.main([__file__, "-v"])



