class TestVersionResolver:
    """Test VersionResolver."""

    @pytest.fixture
    def f_testcontractversioning05_resolver(self):
        versions = ["1.0.0", "1.1.0", "1.2.0", "1.3.0", "2.0.0"]
        return VersionResolver(versions)

    def test_resolve_single_requirement(self, f_testcontractversioning05_resolver):
        """Test resolving single requirement."""
        result = f_testcontractversioning05_resolver.resolve(["^1.2.0"])

        # Should return latest compatible (1.3.0, not 2.0.0)
        assert result == "1.3.0"

    def test_resolve_multiple_requirements(self, f_testcontractversioning05_resolver):
        """Test resolving multiple requirements."""
        result = f_testcontractversioning05_resolver.resolve(["^1.1.0", ">=1.2.0"])

        # Intersection: >=1.2.0, <2.0.0
        # Should return 1.3.0
        assert result == "1.3.0"

    def test_resolve_conflicting_requirements(self, f_testcontractversioning05_resolver):
        """Test resolving conflicting requirements."""
        result = f_testcontractversioning05_resolver.resolve(["^1.0.0", "^2.0.0"])

        # No version satisfies both
        assert result is None

    def test_resolve_exact_match(self, f_testcontractversioning05_resolver):
        """Test resolving to exact version."""
        result = f_testcontractversioning05_resolver.resolve(["1.2.0"])

        assert result == "1.2.0"


