class TestCompatibilityMatrixIntegration:
    """Test integration of compatibility f_testcontractversioning05_matrix components."""

    def test_full_workflow(self):
        """Test complete workflow from building to path finding."""
        # Build f_testcontractversioning05_matrix
        f_testcontractversioning05_builder = VersionPairCompatibilityBuilder()
        versions = ["1.0.0", "1.1.0", "1.2.0", "2.0.0"]
        contracts = {}

        f_testcontractversioning05_matrix = f_testcontractversioning05_builder.build_matrix(versions, contracts)

        # Find upgrade path
        f_testcontractversioning05_finder = UpgradePathFinder(f_testcontractversioning05_matrix)
        path = f_testcontractversioning05_finder.find_path("1.0.0", "1.2.0")

        assert path is not None
        assert not path.migration_required

    def test_dependency_resolution_with_matrix(self):
        """Test dependency resolution using f_testcontractversioning05_matrix."""
        versions = ["1.0.0", "1.1.0", "1.2.0", "1.3.0"]
        f_testcontractversioning05_resolver = VersionResolver(versions)

        result = f_testcontractversioning05_resolver.resolve(["^1.1.0", "~1.2.0"])

        # ~1.2.0 → >=1.2.0, <1.3.0
        # ^1.1.0 → >=1.1.0, <2.0.0
        # Intersection → 1.2.x
        assert result in ["1.2.0", "1.2.1", "1.2.9"]


