# TEST DIFF FORMATTER (10 TESTS)
# ============================================================================
class TestDiffFormatter:
    """Test DiffFormatter (10 tests)."""

    @pytest.fixture
    def f_testcontractversioning07_formatter(self):
        return DiffFormatter()

    @pytest.fixture
    def f_testcontractversioning07_sample_diff(self):
        return DetailedDiff(
            "1.0.0",
            "1.1.0",
            "a" * 64,
            "b" * 64,
            [
                EntityDiff(
                    "struct_Point",
                    "struct",
                    [DetailedChange("size_changed", "struct_Point", ChangeSeverity.BREAKING, "Size changed from 8 to 12 bytes")],
                )
            ],
        )

    def test_format_text_basic(self, f_testcontractversioning07_formatter, f_testcontractversioning07_sample_diff):
        """Test 81: Basic text formatting."""
        text = f_testcontractversioning07_formatter.format_text(f_testcontractversioning07_sample_diff)
        assert "Contract Diff: 1.0.0 → 1.1.0" in text
        assert "struct_Point" in text
        assert "Size changed" in text

    def test_format_text_includes_summary(self, f_testcontractversioning07_formatter, f_testcontractversioning07_sample_diff):
        """Test 82: Text format includes summary."""
        text = f_testcontractversioning07_formatter.format_text(f_testcontractversioning07_sample_diff)
        assert "Summary:" in text
        assert "Total changes:" in text
        assert "Breaking:" in text

    def test_format_text_empty_diff(self, f_testcontractversioning07_formatter):
        """Test 83: Text format for empty diff."""
        diff = DetailedDiff("1.0.0", "1.1.0", "a" * 64, "b" * 64)
        text = f_testcontractversioning07_formatter.format_text(diff)
        assert "Total changes: 0" in text

    def test_format_markdown_basic(self, f_testcontractversioning07_formatter, f_testcontractversioning07_sample_diff):
        """Test 84: Basic markdown formatting."""
        md = f_testcontractversioning07_formatter.format_markdown(f_testcontractversioning07_sample_diff)
        assert "# Contract Diff: 1.0.0 → 1.1.0" in md
        assert "## 🚨 Breaking Changes" in md
        assert "struct_Point" in md

    def test_format_markdown_includes_summary(self, f_testcontractversioning07_formatter, f_testcontractversioning07_sample_diff):
        """Test 85: Markdown includes summary section."""
        md = f_testcontractversioning07_formatter.format_markdown(f_testcontractversioning07_sample_diff)
        assert "## Summary" in md
        assert "Total changes:" in md

    def test_format_markdown_no_breaking(self, f_testcontractversioning07_formatter):
        """Test 86: Markdown without breaking changes."""
        diff = DetailedDiff(
            "1.0.0",
            "1.1.0",
            "a" * 64,
            "b" * 64,
            [EntityDiff("e", "t", [DetailedChange("c", "e", ChangeSeverity.EXTENSION, "Extension change")])],
        )
        md = f_testcontractversioning07_formatter.format_markdown(diff)
        assert "## Summary" in md
        # No breaking section if no breaking changes

    def test_get_severity_badge_all_types(self, f_testcontractversioning07_formatter):
        """Test 87: Severity badges for all types."""
        assert f_testcontractversioning07_formatter._get_severity_badge(DetailedChange("c", "e", ChangeSeverity.BREAKING, "d")) == "BREAKING"
        assert f_testcontractversioning07_formatter._get_severity_badge(DetailedChange("c", "e", ChangeSeverity.EXTENSION, "d")) == "EXTENSION"
        assert (
            f_testcontractversioning07_formatter._get_severity_badge(DetailedChange("c", "e", ChangeSeverity.STRENGTHENING, "d")) == "STRENGTHENING"
        )
        assert f_testcontractversioning07_formatter._get_severity_badge(DetailedChange("c", "e", ChangeSeverity.RELAXATION, "d")) == "RELAXATION"
        assert f_testcontractversioning07_formatter._get_severity_badge(DetailedChange("c", "e", ChangeSeverity.NOTABLE, "d")) == "NOTABLE"
        assert f_testcontractversioning07_formatter._get_severity_badge(DetailedChange("c", "e", ChangeSeverity.NEUTRAL, "d")) == "NEUTRAL"

    def test_get_severity_badge_none(self, f_testcontractversioning07_formatter):
        """Test 88: Severity badge for None."""
        assert f_testcontractversioning07_formatter._get_severity_badge(None) == "UNKNOWN"

    def test_format_text_multiple_entities(self, f_testcontractversioning07_formatter):
        """Test 89: Text format with multiple entities."""
        diff = DetailedDiff(
            "1.0.0",
            "1.1.0",
            "a" * 64,
            "b" * 64,
            [
                EntityDiff("struct_Point", "struct", [DetailedChange("c1", "e1", ChangeSeverity.BREAKING, "Change 1")]),
                EntityDiff("function_process", "function", [DetailedChange("c2", "e2", ChangeSeverity.EXTENSION, "Change 2")]),
            ],
        )
        text = f_testcontractversioning07_formatter.format_text(diff)
        assert "struct_Point" in text
        assert "function_process" in text

    def test_format_markdown_multiple_breaking(self, f_testcontractversioning07_formatter):
        """Test 90: Markdown with multiple breaking changes."""
        diff = DetailedDiff(
            "1.0.0",
            "2.0.0",
            "a" * 64,
            "b" * 64,
            [
                EntityDiff("e1", "t", [DetailedChange("c1", "e1", ChangeSeverity.BREAKING, "Breaking 1")]),
                EntityDiff("e2", "t", [DetailedChange("c2", "e2", ChangeSeverity.BREAKING, "Breaking 2")]),
            ],
        )
        md = f_testcontractversioning07_formatter.format_markdown(diff)
        assert "Breaking 1" in md
        assert "Breaking 2" in md


