# TEST DETAILED DIFF ANALYZER (10 TESTS)
# ============================================================================
class TestDetailedDiffAnalyzer:
    """Test DetailedDiffAnalyzer (10 tests)."""

    @pytest.fixture
    def f_testcontractversioning07_analyzer(self):
        return DetailedDiffAnalyzer()

    @pytest.fixture
    def f_testcontractversioning07_mock_contract_v1(self):
        class MockContract:
            contract_version = "1.0.0"
            contract_fingerprint = "a" * 64

        return MockContract()

    @pytest.fixture
    def f_testcontractversioning07_mock_contract_v2(self):
        class MockContract:
            contract_version = "1.1.0"
            contract_fingerprint = "b" * 64

        return MockContract()

    def test_analyze_returns_detailed_diff(self, f_testcontractversioning07_analyzer, f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2):
        """Test 91: analyze returns DetailedDiff."""
        diff = f_testcontractversioning07_analyzer.analyze(f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2)
        assert isinstance(diff, DetailedDiff)

    def test_analyze_sets_versions(self, f_testcontractversioning07_analyzer, f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2):
        """Test 92: analyze sets baseline and candidate versions."""
        diff = f_testcontractversioning07_analyzer.analyze(f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2)
        assert diff.baseline_version == "1.0.0"
        assert diff.candidate_version == "1.1.0"

    def test_analyze_sets_fingerprints(self, f_testcontractversioning07_analyzer, f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2):
        """Test 93: analyze sets fingerprints."""
        diff = f_testcontractversioning07_analyzer.analyze(f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2)
        assert diff.baseline_fingerprint == "a" * 64
        assert diff.candidate_fingerprint == "b" * 64

    def test_analyze_handles_missing_version(self, f_testcontractversioning07_analyzer):
        """Test 94: analyze handles missing version attribute."""

        class MockContract:
            contract_fingerprint = "a" * 64

        diff = f_testcontractversioning07_analyzer.analyze(MockContract(), MockContract())
        assert diff.baseline_version == "unknown"
        assert diff.candidate_version == "unknown"

    def test_analyze_handles_missing_fingerprint(self, f_testcontractversioning07_analyzer):
        """Test 95: analyze handles missing fingerprint attribute."""

        class MockContract:
            contract_version = "1.0.0"

        diff = f_testcontractversioning07_analyzer.analyze(MockContract(), MockContract())
        assert diff.baseline_fingerprint == ""
        assert diff.candidate_fingerprint == ""

    def test_analyze_initializes_entity_diffs(self, f_testcontractversioning07_analyzer, f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2):
        """Test 96: analyze initializes entity_diffs list."""
        diff = f_testcontractversioning07_analyzer.analyze(f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2)
        assert isinstance(diff.entity_diffs, list)

    def test_analyze_placeholder_returns_empty(self, f_testcontractversioning07_analyzer, f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2):
        """Test 97: Placeholder implementations return empty."""
        diff = f_testcontractversioning07_analyzer.analyze(f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2)
        # Placeholder implementations return empty lists
        assert len(diff.entity_diffs) == 0

    def test_analyze_same_contract(self, f_testcontractversioning07_analyzer, f_testcontractversioning07_mock_contract_v1):
        """Test 98: analyze comparing same contract."""
        diff = f_testcontractversioning07_analyzer.analyze(f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v1)
        assert diff.baseline_fingerprint == diff.candidate_fingerprint

    def test_analyze_to_dict(self, f_testcontractversioning07_analyzer, f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2):
        """Test 99: Analyzed diff can convert to dict."""
        diff = f_testcontractversioning07_analyzer.analyze(f_testcontractversioning07_mock_contract_v1, f_testcontractversioning07_mock_contract_v2)
        data = diff.to_dict()
        assert "baseline_version" in data
        assert "candidate_version" in data
        assert "statistics" in data

