class TestVersionRangeParser:
    """Test VersionRangeParser (5 tests)."""

    @pytest.fixture
    def f_testcontractversioning16_parser(self):
        return VersionRangeParser()

    def test_parse_greater_equal(self, f_testcontractversioning16_parser):
        """Test 71: Parse >= range."""
        result = f_testcontractversioning16_parser.parse_range(">=1.0.0")
        assert result["type"] == "greater_equal"
        assert result["version"] == "1.0.0"

    def test_parse_caret(self, f_testcontractversioning16_parser):
        """Test 72: Parse caret range."""
        result = f_testcontractversioning16_parser.parse_range("^1.5.0")
        assert result["type"] == "caret"

    def test_satisfies_greater_equal(self, f_testcontractversioning16_parser):
        """Test 73: Satisfies >= range."""
        assert f_testcontractversioning16_parser.satisfies_range("1.5.0", ">=1.0.0") is True
        assert f_testcontractversioning16_parser.satisfies_range("0.9.0", ">=1.0.0") is False

    def test_satisfies_caret(self, f_testcontractversioning16_parser):
        """Test 74: Satisfies caret range."""
        assert f_testcontractversioning16_parser.satisfies_range("1.5.0", "^1.0.0") is True
        assert f_testcontractversioning16_parser.satisfies_range("2.0.0", "^1.0.0") is False

    def test_parse_exact(self, f_testcontractversioning16_parser):
        """Test 75: Parse exact version."""
        result = f_testcontractversioning16_parser.parse_range("1.2.3")
        assert result["type"] == "exact"
        assert result["version"] == "1.2.3"


if __name__ == "__main__":
    pytest.main([__file__, "-v"])



