    def test_validate_structure(self, f_testlanguageadapter01_sample_contract):
        """Test 93: Validate structure."""
        p = ContractProjector()
        p._validate_contract_structure(f_testlanguageadapter01_sample_contract)
    
    def test_missing_field_raises(self):
        """Test 94: Missing field raises."""
