class MockIRUnit:
    def __init__(self, symbols=None, types=None):
        self.symbols = symbols or []
        self.types = types or []

def generate_large_ir(num_functions=1, num_types=1):
    # num_types + 1 because of the base int32 type
    types = [f"t{i}" for i in range(num_types)] + ["int32"]
    return MockIRUnit(symbols=[f"f{i}" for i in range(num_functions)], 
                     types=types)

